export function loadAllItemIcons(scene, assetPrefix = './assets/') {
  GAME_ITEM_ICONS.forEach(([key, path]) => {
    if (!scene.textures.exists(key)) {
      scene.load.image(key, assetPrefix + path);
    }
  });
}
